import{_ as l,o as i,c as o,a as e}from"./app-be7ae715.js";const t={},n=e("<ol><li>盒子模型</li><li>选择器</li><li><code>em/px/rem/vh/vw</code></li><li>像素 <ol><li>css像素 (px) ，受 PPI 和 DPR 影响</li><li>设备像素(pt)， 即物理像素</li><li>独立设备像素，逻辑像素</li><li>dpr 设备像素比 <code>window.devicePixelRatio</code> 2:1 -&gt; 2*2 个物理像素表示一个css像素</li><li>ppi 每英寸像素，即像素密度</li></ol></li><li>隐藏页面元素 <ul><li>display:none</li><li>visibility:hidden</li><li>opacity:0</li><li>设置height、width模型属性为0</li><li>position:absolute</li><li>clip-path</li></ul></li><li>BFC <ol><li>是什么： 独立渲染上下文 <ul><li>对于同一个BFC的俩个相邻的盒子的margin会发生重叠</li><li>每个元素的左外边距与包含块的左边界相接触（从左到右），即使浮动元素也是如此</li><li>BFC的区域不会与float的元素区域重叠</li><li>计算BFC的高度时，浮动子元素也参与计算</li></ul></li><li>如何触发 <ul><li>根元素，即HTML元素</li><li>浮动元素：float值为left、right</li><li>overflow值不为 visible</li><li>display的值为inline-block、inltable-cell、table-caption、table、inline-table、flex、inline-flex、grid、inline-grid</li><li>position的值为absolute或fixed</li></ul></li></ol></li><li>两栏布局和三栏布局 <ol><li>table布局</li><li>flex布局</li><li>grid布局</li><li>margin float布局</li></ol></li><li>浮动(float) <ol><li>清除自身文档空间，向原本空间一侧浮动</li><li>下方文档填补空缺，有浮动则重复以上步骤</li></ol></li><li>flex弹性布局</li><li>grid</li><li>回流重绘 <ol><li>回流：当DOM元素几何性质发生变化(大小),浏览器不可避免的对相关的DOM节点进行几何大小和位置的计算。 <ol><li>增改DOM元素</li><li>元素位置尺寸变化</li><li>浏览器窗口变化</li><li>页面初始渲染</li><li>offsetTop等视口值的获取</li></ol></li><li>重绘： 一个元素的几何大小和位置没有变化，只有元素内部的样式发生变化，引起元素内部的重绘，绘制新的样式(颜色，文本方向等)</li></ol></li><li>响应式设计 <ol><li>媒体查询</li><li>rem/vh/vw</li><li>percent</li></ol></li><li>CSS 性能优化 <ol><li>首屏关键样式内联</li><li>异步加载CSS</li><li>资源压缩</li><li>合理使用选择器</li><li>减少昂贵属性使用</li></ol></li></ol>",1),a=[n];function c(s,d){return i(),o("div",null,a)}const f=l(t,[["render",c],["__file","CSS.html.vue"]]);export{f as default};
